"""自定义异常模块。

本模块定义了嵌入服务中使用的所有自定义异常类，
提供更精细的错误处理和更清晰的错误信息。

Typical usage example:
    from utils.exceptions import ModelLoadError, TextTooLongError

    try:
        model = load_model(path)
    except ModelLoadError as e:
        logger.error(f"模型加载失败: {e}")
"""

from typing import Any, Optional


class EmbeddingServiceError(Exception):
    """嵌入服务基础异常类。

    所有自定义异常的基类，提供统一的错误信息格式。

    Attributes:
        message: 错误信息描述。
        error_code: 错误代码，用于 API 响应。
        details: 额外的错误详情。
    """

    def __init__(
        self,
        message: str,
        error_code: str = "EMBEDDING_ERROR",
        details: Optional[dict[str, Any]] = None
    ):
        """初始化异常实例。

        Args:
            message: 错误描述信息。
            error_code: 错误代码标识符。
            details: 可选的错误详情字典。
        """
        self.message = message
        self.error_code = error_code
        self.details = details or {}
        super().__init__(self.message)

    def to_dict(self) -> dict[str, Any]:
        """将异常转换为字典格式。

        Returns:
            包含错误信息的字典，适用于 API 响应。
        """
        return {
            "error_code": self.error_code,
            "message": self.message,
            "details": self.details
        }

    def __str__(self) -> str:
        """返回格式化的错误字符串。"""
        if self.details:
            return f"[{self.error_code}] {self.message} | Details: {self.details}"
        return f"[{self.error_code}] {self.message}"


# ==============================================================================
# 模型相关异常
# ==============================================================================


class ModelError(EmbeddingServiceError):
    """模型相关错误基类。"""

    def __init__(
        self,
        message: str,
        error_code: str = "MODEL_ERROR",
        details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message, error_code, details)


class ModelLoadError(ModelError):
    """模型加载失败异常。

    当模型文件不存在、格式错误或加载过程中出现其他问题时抛出。
    """

    def __init__(
        self,
        message: str = "模型加载失败",
        model_name: Optional[str] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if model_name:
            details["model_name"] = model_name
        super().__init__(message, "MODEL_LOAD_ERROR", details)


class ModelInferenceError(ModelError):
    """模型推理失败异常。

    当模型推理过程中出现错误时抛出。
    """

    def __init__(
        self,
        message: str = "模型推理失败",
        batch_size: Optional[int] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if batch_size is not None:
            details["batch_size"] = batch_size
        super().__init__(message, "MODEL_INFERENCE_ERROR", details)


class ModelNotInitializedError(ModelError):
    """模型未初始化异常。

    当尝试使用未初始化的模型进行推理时抛出。
    """

    def __init__(
        self,
        message: str = "模型尚未初始化",
        details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message, "MODEL_NOT_INITIALIZED", details)


# ==============================================================================
# GPU/设备相关异常
# ==============================================================================


class DeviceError(EmbeddingServiceError):
    """设备相关错误基类。"""

    def __init__(
        self,
        message: str,
        error_code: str = "DEVICE_ERROR",
        details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message, error_code, details)


class GPUOutOfMemoryError(DeviceError):
    """GPU 显存不足异常。

    当 CUDA 显存不足以完成操作时抛出。
    """

    def __init__(
        self,
        message: str = "GPU 显存不足",
        required_memory: Optional[str] = None,
        available_memory: Optional[str] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if required_memory:
            details["required_memory"] = required_memory
        if available_memory:
            details["available_memory"] = available_memory
        super().__init__(message, "GPU_OOM_ERROR", details)


class DeviceNotAvailableError(DeviceError):
    """设备不可用异常。

    当指定的计算设备（如 CUDA GPU）不可用时抛出。
    """

    def __init__(
        self,
        message: str = "指定的计算设备不可用",
        requested_device: Optional[str] = None,
        available_devices: Optional[list[str]] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if requested_device:
            details["requested_device"] = requested_device
        if available_devices:
            details["available_devices"] = available_devices
        super().__init__(message, "DEVICE_NOT_AVAILABLE", details)


# ==============================================================================
# 文本处理相关异常
