class TextProcessingError(EmbeddingServiceError):
    """文本处理错误基类。"""

    def __init__(
        self,
        message: str,
        error_code: str = "TEXT_PROCESSING_ERROR",
        details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message, error_code, details)


class TextTooLongError(TextProcessingError):
    """文本过长异常。

    当输入文本超过允许的最大长度时抛出。
    """

    def __init__(
        self,
        message: str = "输入文本超过最大长度限制",
        text_length: Optional[int] = None,
        max_length: Optional[int] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if text_length is not None:
            details["text_length"] = text_length
        if max_length is not None:
            details["max_length"] = max_length
        super().__init__(message, "TEXT_TOO_LONG", details)


class EmptyTextError(TextProcessingError):
    """空文本异常。

    当输入文本为空或仅包含空白字符时抛出。
    """

    def __init__(
        self,
        message: str = "输入文本为空",
        text_index: Optional[int] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if text_index is not None:
            details["text_index"] = text_index
        super().__init__(message, "EMPTY_TEXT", details)


class TextSplitError(TextProcessingError):
    """文本分割异常。

    当文本分割过程中出现错误时抛出。
    """

    def __init__(
        self,
        message: str = "文本分割失败",
        text_length: Optional[int] = None,
        chunk_size: Optional[int] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if text_length is not None:
            details["text_length"] = text_length
        if chunk_size is not None:
            details["chunk_size"] = chunk_size
        super().__init__(message, "TEXT_SPLIT_ERROR", details)


# ==============================================================================
# 批处理相关异常
