class BatchProcessingError(EmbeddingServiceError):
    """批处理错误基类。"""

    def __init__(
        self,
        message: str,
        error_code: str = "BATCH_PROCESSING_ERROR",
        details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message, error_code, details)


class BatchSizeError(BatchProcessingError):
    """批次大小错误异常。

    当批次大小超出允许范围时抛出。
    """

    def __init__(
        self,
        message: str = "批次大小无效",
        batch_size: Optional[int] = None,
        max_batch_size: Optional[int] = None,
        min_batch_size: int = 1,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if batch_size is not None:
            details["batch_size"] = batch_size
        if max_batch_size is not None:
            details["max_batch_size"] = max_batch_size
        details["min_batch_size"] = min_batch_size
        super().__init__(message, "INVALID_BATCH_SIZE", details)


class EmptyBatchError(BatchProcessingError):
    """空批次异常。

    当输入批次为空时抛出。
    """

    def __init__(
        self,
        message: str = "输入批次为空",
        details: Optional[dict[str, Any]] = None
    ):
        super().__init__(message, "EMPTY_BATCH", details)


# ==============================================================================
# API 相关异常
# ==============================================================================


class APIError(EmbeddingServiceError):
    """API 错误基类。"""

    def __init__(
        self,
        message: str,
        error_code: str = "API_ERROR",
        http_status: int = 500,
        details: Optional[dict[str, Any]] = None
    ):
        self.http_status = http_status
        super().__init__(message, error_code, details)


class ValidationError(APIError):
    """请求验证错误异常。

    当请求参数验证失败时抛出。
    """

    def __init__(
        self,
        message: str = "请求参数验证失败",
        field: Optional[str] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if field:
            details["field"] = field
        super().__init__(message, "VALIDATION_ERROR", 400, details)


class RateLimitError(APIError):
    """请求频率限制异常。

    当请求超过频率限制时抛出。
    """

    def __init__(
        self,
        message: str = "请求频率超过限制",
        retry_after: Optional[int] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if retry_after is not None:
            details["retry_after_seconds"] = retry_after
        super().__init__(message, "RATE_LIMIT_EXCEEDED", 429, details)


class ServiceUnavailableError(APIError):
    """服务不可用异常。

    当服务暂时不可用时抛出。
    """

    def __init__(
        self,
        message: str = "服务暂时不可用",
        reason: Optional[str] = None,
        details: Optional[dict[str, Any]] = None
    ):
        details = details or {}
        if reason:
            details["reason"] = reason
        super().__init__(message, "SERVICE_UNAVAILABLE", 503, details)


# ==============================================================================
# 异常处理工具函数
# ==============================================================================


def is_gpu_oom_error(exception: Exception) -> bool:
    """检查异常是否为 GPU 显存不足错误。

    Args:
        exception: 要检查的异常实例。

    Returns:
        如果是 GPU OOM 错误返回 True，否则返回 False。
    """
    error_msg = str(exception).lower()
    oom_keywords = [
        "out of memory",
        "cuda out of memory",
        "cuda error: out of memory",
        "cudnn_status_not_enough_memory",
        "cublas_status_alloc_failed"
    ]
    return any(keyword in error_msg for keyword in oom_keywords)


def wrap_exception(
    exception: Exception,
    default_class: type[EmbeddingServiceError] = EmbeddingServiceError
) -> EmbeddingServiceError:
    """将标准异常包装为自定义异常。

    根据异常类型自动选择合适的自定义异常类进行包装。

    Args:
        exception: 原始异常实例。
        default_class: 默认的自定义异常类。

    Returns:
        包装后的自定义异常实例。
    """
    # 如果已经是自定义异常，直接返回
    if isinstance(exception, EmbeddingServiceError):
        return exception

    # 检查是否为 GPU OOM 错误
    if is_gpu_oom_error(exception):
        return GPUOutOfMemoryError(
            message=f"GPU 显存不足: {exception}",
            details={"original_error": str(exception)}
        )

    # 检查是否为文件/模型加载错误
    if isinstance(exception, (FileNotFoundError, OSError)):
        return ModelLoadError(
            message=f"文件或模型加载失败: {exception}",
            details={"original_error": str(exception)}
        )

    # 检查是否为值错误
    if isinstance(exception, ValueError):
        return TextProcessingError(
            message=f"文本处理错误: {exception}",
            details={"original_error": str(exception)}
        )

    # 默认包装
    return default_class(
        message=str(exception),
        details={
            "original_error_type": type(exception).__name__,
            "original_error": str(exception)
        }
    )
